/** lat/lon → coordinate nel viewBox della mappa */
const geoToXY = (lat, lon) => ({
  x: ((lon + 180) / 360) * MAP_W,
  y: ((MAP_LAT_TOP - Math.max(MAP_LAT_BOT, Math.min(MAP_LAT_TOP, lat))) / (MAP_LAT_TOP - MAP_LAT_BOT)) * MAP_H,
});

/** distanza in km tra due punti (haversine) */
const haversine = (a, b) => {
  const R = 6371, toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]), dLon = toRad(b[1] - a[1]);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.sin(dLon / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(h)));
};

const countryLabel = (nm) => (COUNTRY_META[nm] ? COUNTRY_META[nm][0] : nm);
const countryFlag = (nm) => (COUNTRY_META[nm] ? COUNTRY_META[nm][1] : "🌍");
const countryRegion = (nm) => (COUNTRY_META[nm] ? COUNTRY_META[nm][2] : "");

const photoService = {
  _cache: new Map(),
  _langs: ["it", "en"],
  /* pagine che non rappresentano mai una meta */
  _bad(t) { return /disambigua|disambiguation|\(film\)|\(album\)|\(azienda\)|\(gruppo|società|s\.p\.a|stazione di|aeroporto|ospedale|liceo|università degli studi|linea \d|metropolitana di|elezioni|storia di|economia di|geografia di|provincia di|comune di|arcidiocesi|diocesi/i.test(t); },
  _norm(s) { return (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim(); },

  /** monumenti e attrazioni attorno al punto, ordinati per popolarità reale */
  async byLandmark(lat, lon, lang, nomeLuogo) {
    const url = `https://${lang}.wikipedia.org/w/api.php?action=query&format=json&origin=*` +
      `&generator=geosearch&ggscoord=${lat}%7C${lon}&ggsradius=10000&ggslimit=40` +
      `&prop=pageimages|coordinates|pageviews&piprop=thumbnail&pithumbsize=1600&pvipdays=60`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const pages = Object.values((await res.json())?.query?.pages || {});
    const luogo = this._norm(nomeLuogo);
    const scored = pages
      .filter((p) => p.thumbnail?.source && !this._bad(p.title))
      .map((p) => ({
        title: p.title,
        img: p.thumbnail.source,
        /* somma delle visite giornaliere = quanto è conosciuto */
        views: Object.values(p.pageviews || {}).reduce((s, v) => s + (v || 0), 0),
        isLuogo: this._norm(p.title) === luogo,
      }))
      .sort((a, b) => b.views - a.views);
    if (!scored.length) return null;
    /* il simbolo della città: il più visitato che non sia la città stessa */
    const simbolo = scored.find((p) => !p.isLuogo && p.views > 0);
    const cityPage = scored.find((p) => p.isLuogo);
    const best = simbolo || cityPage || scored[0];
    return { img: best.img, title: best.title, alt: scored.filter((p) => p !== best).slice(0, 7).map((p) => p.img) };
  },

  /** articolo con quel titolo esatto (ripiego, e per luoghi che sono essi stessi l'attrazione) */
  async byTitle(titolo, lang, near) {
    if (!titolo) return null;
    const res = await fetch(`https://${lang}.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(titolo)}?redirect=true`);
    if (!res.ok) return null;
    const j = await res.json();
    if (j.type === "disambiguation" || !j.thumbnail?.source) return null;
    if (near && j.coordinates && haversine([j.coordinates.lat, j.coordinates.lon], near) > 80) return null;
    return { img: j.originalimage?.source || j.thumbnail.source, title: j.title, alt: [] };
  },

  /** ricerca testuale, accettata solo se geograficamente coerente */
  async bySearch(query, lang, near) {
    const url = `https://${lang}.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrsearch=${encodeURIComponent(query)}&gsrlimit=5&prop=pageimages|coordinates&piprop=thumbnail&pithumbsize=1600`;
    const res = await fetch(url);
    if (!res.ok) return null;
    const pages = Object.values((await res.json())?.query?.pages || {})
      .filter((p) => p.thumbnail?.source && !this._bad(p.title))
      .sort((a, b) => (a.index || 9) - (b.index || 9));
    for (const p of pages) {
      const c = p.coordinates?.[0];
      if (near && (!c || haversine([c.lat, c.lon], near) > 80)) continue;
      return { img: p.thumbnail.source, title: p.title, alt: [] };
    }
    return null;
  },

  /** risultato completo: immagine scelta, titolo e alternative da scorrere */
  async lookup(citta, paese, lat, lon) {
    const key = `${citta}|${paese}|${lat}`;
    if (this._cache.has(key)) return this._cache.get(key);
    const near = lat != null && lon != null ? [lat, lon] : null;
    const nome = (citta || "").trim();
    let out = null;
    for (const lang of this._langs) {
      try { if (near) out = await this.byLandmark(lat, lon, lang, nome); } catch {}
      if (out?.img) break;
      try { out = await this.byTitle(nome, lang, near); } catch {}
      if (out?.img) break;
      try { out = await this.bySearch(`${nome} ${paese ? countryLabel(paese) : ""}`.trim(), lang, near); } catch {}
      if (out?.img) break;
      try { if (!nome && paese) out = await this.byTitle(countryLabel(paese), lang, null); } catch {}
      if (out?.img) break;
    }
    const val = out?.img ? out : null;
    this._cache.set(key, val);
    return val;
  },

  async best(citta, paese, lat, lon) { return (await this.lookup(citta, paese, lat, lon))?.img || null; },
  async candidates(citta, paese, lat, lon) {
    const r = await this.lookup(citta, paese, lat, lon);
    return r ? [r.img, ...(r.alt || [])] : [];
  },
};

const geocodingService = {
  _cache: new Map(),
  local(q) {
    const ql = q.trim().toLowerCase();
    if (!ql) return [];
    return CITIES.filter(([nm, co]) => nm.toLowerCase().includes(ql) || countryLabel(co).toLowerCase().includes(ql))
      .slice(0, 6)
      .map(([nm, co, la, lo]) => ({ nome: nm, paese: co, lat: la, lon: lo, tipo: "città", fonte: "locale" }));
  },
  async search(q, signal) {
    const key = q.trim().toLowerCase();
    if (!key) return [];
    if (this._cache.has(key)) return this._cache.get(key);
    const url = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&accept-language=it&limit=6&q=${encodeURIComponent(q)}`;
    const res = await fetch(url, { signal, headers: { Accept: "application/json" } });
    if (!res.ok) throw new Error("geocoding non disponibile");
    const raw = await res.json();
    const out = raw.map((r) => {
      const cc = (r.address?.country_code || "").toUpperCase();
      const paese = Object.keys(COUNTRY_META).find((k) => COUNTRY_META[k][5] === cc || COUNTRY_META[k][0] === r.address?.country || k === r.address?.country) || r.address?.country || "";
      return {
        nome: (r.name || r.display_name.split(",")[0]).trim(),
        etichetta: r.display_name,
        paese, lat: +r.lat, lon: +r.lon,
        tipo: (r.type || r.category || "luogo").replace(/_/g, " "),
        fonte: "osm",
      };
    }).filter((x) => x.paese);
    this._cache.set(key, out);
    return out;
  },
};

